const CONFIG = {
  lineToken: 'OSuAp+bFgLfWZC0Vf/eehMgzFSBpZer1FaTVBF5xUn3R9Hf5OqIZfG5xnC1rFv02p2wycGYSqaSPckSWEfuuZnllRJhYSuECp4PyXOxnY4yCkluxiM0c0JIQiS2EtQyDCHQbjyd4LkK1byL5A6sw/AdB04t89/1O/w1cDnyilFU=',
  crmToken: 'ee3133cb65d162bd96d9610c0080d56f0803ff82c0088b2c4d0d85ed2088cfdf',
  crmBaseUrl: 'https://test-web.eimaths-th.com',
  marketingGroupId: 'PUT_LINE_MARKETING_GROUP_ID_HERE'
};

function NormalizeText(value) {
  return String(value || '').trim().replace(/\s+/g, ' ');
}

const body = $json.body || $json;
const events = Array.isArray(body.events) ? body.events : [];

return events
  .filter((event) => event.source?.userId && ['follow', 'message'].includes(event.type))
  .filter((event) => event.type !== 'message' || event.message?.type === 'text')
  .map((event) => {
    const message_text = NormalizeText(event.message?.text || '');
    return {
      json: {
        config: CONFIG,
        eventType: event.type,
        lineUserId: event.source.userId,
        replyToken: event.replyToken,
        messageText: message_text,
        normalizedText: message_text,
        lowerText: message_text.toLowerCase(),
        eventTimestamp: new Date(event.timestamp || Date.now()).toISOString()
      }
    };
  });

const item = $json || {};
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};

const now_iso = new Date().toISOString();
const line_user_id = item.lineUserId;

const default_conversation = {
  state: 'waiting_consent',
  consentStatus: 'pending',
  answers: {},
  currentStudentIndex: 0,
  createdAt: now_iso,
  startedAt: now_iso,
  followedAt: item.eventType === 'follow' ? now_iso : null,
  lastMessageAt: now_iso,
  invalidCountByState: {},
  handoverReplyCount: 0,
  postCompletionReplyCount: 0,
  handoverNotifiedAt: null,
  handoverReason: null,
  completedAt: null
};

const conversation = store.conversations[line_user_id] || default_conversation;
conversation.answers = conversation.answers || {};
conversation.currentStudentIndex = Number(conversation.currentStudentIndex || 0);
conversation.invalidCountByState = conversation.invalidCountByState || {};
conversation.lastMessageAt = now_iso;
conversation.displayName = item.displayName || conversation.displayName || null;
conversation.pictureUrl = item.pictureUrl || conversation.pictureUrl || null;
if (item.eventType === 'follow' && !conversation.followedAt) conversation.followedAt = now_iso;

store.conversations[line_user_id] = conversation;

return {
  json: {
    ...item,
    nowIso: now_iso,
    conversationState: conversation.state,
    consentStatus: conversation.consentStatus || 'pending',
    existingAnswers: conversation.answers,
    currentStudentIndex: conversation.currentStudentIndex,
    invalidCountByState: conversation.invalidCountByState,
    handoverReplyCount: Number(conversation.handoverReplyCount || 0),
    postCompletionReplyCount: Number(conversation.postCompletionReplyCount || 0),
    handoverNotifiedAt: conversation.handoverNotifiedAt || null,
    handoverReason: conversation.handoverReason || null,
    completedAt: conversation.completedAt || null,
    displayName: conversation.displayName,
    pictureUrl: conversation.pictureUrl
  }
};

const item = $json || {};
const text = String(item.normalizedText || '').trim();
const lower_text = text.toLowerCase();

function IncludesAny(values) {
  return values.some((keyword) => lower_text.includes(keyword.toLowerCase()));
}

const restart_keywords = [
  'เริ่มใหม่', 'ลงทะเบียนใหม่', 'แก้ข้อมูล', 'กรอกใหม่', 'สมัครใหม่',
  'เริ่มลงทะเบียน', 'ลงใหม่', 'ทำใหม่', 'เริ่มอีกรอบ', 'restart', 'reset', 'clear'
];
const staff_keywords = [
  'ติดต่อเจ้าหน้าที่', 'คุยกับแอดมิน', 'คุยกับคน', 'ขอคนตอบ',
  'เจ้าหน้าที่', 'แอดมิน', 'ให้คนติดต่อ', 'ให้เจ้าหน้าที่ติดต่อ'
];
const cancel_keywords = ['ยกเลิก', 'ไม่ลงทะเบียน', 'พอก่อน', 'ไม่สะดวกแล้ว'];

let direct_decision = null;

// ให้เริ่มใหม่มี priority สูงสุด เพื่อให้ user ที่เคยกรอกจบหรืออยู่ silent handover reset ได้เสมอ
if (IncludesAny(restart_keywords)) {
  direct_decision = {
    action: 'restart_registration',
    reason: 'user_requested_restart',
    replyText: ''
  };
} else if (IncludesAny(staff_keywords)) {
  direct_decision = {
    action: 'handover_to_staff',
    reason: 'user_requested_staff',
    replyText: 'ได้เลยค่ะ 😊 เดี๋ยวบอทส่งเรื่องให้เจ้าหน้าที่เข้ามาดูแลต่อนะคะ\nระหว่างนี้สามารถพิมพ์คำถามหรือรายละเอียดเพิ่มเติมไว้ได้เลยค่ะ'
  };
} else if (IncludesAny(cancel_keywords)) {
  direct_decision = {
    action: 'cancel_registration',
    reason: 'user_requested_cancel',
    replyText: 'เข้าใจค่ะ 😊 ตอนนี้บอทจะหยุดขั้นตอนลงทะเบียนไว้ก่อนนะคะ\nหากต้องการเริ่มใหม่ สามารถพิมพ์ “เริ่มใหม่” หรือพิมพ์ “ติดต่อเจ้าหน้าที่” ได้เลยค่ะ'
  };
}

return {
  json: {
    ...item,
    directDecision: direct_decision,
    hasDirectDecision: Boolean(direct_decision)
  }
};

const item = $json || {};
const text = String(item.normalizedText || '').trim();
const lower_text = text.toLowerCase();
const current_state = item.conversationState || 'waiting_consent';
const consent_status = item.consentStatus || 'pending';
const is_registration_completed = Boolean(item.completedAt) || item.handoverReason === 'registration_completed';

const questions = {
  waiting_parent_name: `รบกวนขอชื่อหรือชื่อเล่นของคุณพ่อ/คุณแม่ที่สะดวกให้ติดต่อกลับหน่อยค่ะ 😊\nเช่น แม่ก้อย, คุณพ่อนัท หรือคุณแม่แอนค่ะ`,
  waiting_phone: 'ขอเบอร์โทรที่สะดวกให้ทีมงานติดต่อกลับหน่อยนะคะ',
  waiting_student_count: 'ต้องการลงทะเบียนทดลองเรียนฟรีให้น้องกี่คนคะ 😊\nพิมพ์ได้เลย เช่น 1 คน, 2 คน หรือ คนเดียวค่ะ',
  waiting_student_name: 'น้องชื่ออะไรคะ จะได้ให้ทีมงานเรียกชื่อน้องถูกค่ะ 😊',
  waiting_student_grade: 'ตอนนี้น้องอยู่ระดับชั้นไหนคะ เช่น อนุบาล 1, ป.1 หรือ ป.6',
  waiting_pain_point: `ตอนนี้อยากให้ eiMaths ช่วยน้องเรื่องไหนเป็นพิเศษคะ\nเช่น ไม่ชอบคณิต, กลัวเลข, ทำโจทย์ไม่ค่อยได้, เรียนไม่ทัน หรืออยากเพิ่มความมั่นใจ`,
  waiting_preferred_contact_time: `คุณพ่อ/คุณแม่สะดวกให้ทีมงานติดต่อกลับช่วงเวลาไหนคะ\nเช่น หลัง 18:00 หรือช่วงเย็นหลังเลิกงาน`
};

function IncludesAny(values) {
  return values.some((keyword) => lower_text.includes(keyword.toLowerCase()));
}

function EqualsAny(values) {
  return values.some((keyword) => lower_text === keyword.toLowerCase());
}

function IsConsentDecline() {
  const exact_decline_keywords = [
    'ไม่ยินยอม', 'ไม่ยินยอมค่ะ', 'ไม่ยินยอมครับ', 'ไม่อนุญาต',
    'ไม่ให้เก็บข้อมูล', 'ไม่ให้ข้อมูล', 'ไม่สะดวกให้ข้อมูล', 'ยังไม่สะดวกให้ข้อมูล',
    'ขอไม่ให้ข้อมูล', 'ขอคิดก่อน'
  ];
  const phrase_decline_keywords = [
    'ไม่ยินยอม', 'ไม่อนุญาต', 'ไม่ให้เก็บข้อมูล', 'ไม่ให้ข้อมูล',
    'ไม่สะดวกให้ข้อมูล', 'ยังไม่สะดวกให้ข้อมูล', 'ขอไม่ให้ข้อมูล', 'ขอคิดก่อน'
  ];

  return EqualsAny(exact_decline_keywords) || phrase_decline_keywords.some((keyword) => lower_text.includes(keyword));
}

function IsConsentAccept() {
  const exact_accept_keywords = [
    'ยินยอม', 'ยินยอมค่ะ', 'ยินยอมครับ', 'ตกลง', 'ตกลงค่ะ', 'ตกลงครับ',
    'อนุญาต', 'อนุญาตค่ะ', 'อนุญาตครับ', 'ได้ค่ะ', 'ได้ครับ', 'ได้เลย',
    'โอเค', 'ok', 'okay', 'สนใจ', 'ลงทะเบียน'
  ];
  const phrase_accept_keywords = [
    'ยินยอมให้เก็บข้อมูล', 'อนุญาตให้เก็บข้อมูล', 'เริ่มลงทะเบียน', 'อยากลงทะเบียน', 'ขอลงทะเบียน'
  ];

  if (IsConsentDecline()) return false;
  return EqualsAny(exact_accept_keywords) || phrase_accept_keywords.some((keyword) => lower_text.includes(keyword));
}

function ConsentIntroText() {
  return [
    'สวัสดีค่ะ 😊',
    'ตอนนี้คุณกำลังคุยกับผู้ช่วยอัตโนมัติของ eiMaths นะคะ',
    '',
    'บอทจะช่วยเก็บข้อมูลเบื้องต้น เพื่อให้ทีมงานแนะนำคลาสทดลองเรียนฟรีที่เหมาะกับน้องได้ตรงมากขึ้นค่ะ',
    '',
    'ก่อนเริ่มลงทะเบียน ขออนุญาตเก็บข้อมูล เช่น ชื่อผู้ปกครอง เบอร์โทร ชื่อน้อง ระดับชั้น และช่วงเวลาที่สะดวกให้ติดต่อกลับนะคะ',
    '',
    'ข้อมูลนี้ใช้เพื่อให้ทีมงาน eiMaths ติดต่อกลับและแนะนำคลาสทดลองเรียนฟรีเท่านั้นค่ะ',
    '',
    'หากยินยอมให้เก็บข้อมูล พิมพ์ “ยินยอม”',
    'หากยังไม่สะดวกให้เก็บข้อมูล พิมพ์ “ไม่ยินยอม”',
    'หรือพิมพ์ “ติดต่อเจ้าหน้าที่” เพื่อให้ทีมงานดูแลต่อค่ะ'
  ].join('\n');
}

function PostCompletionOptionsText() {
  return [
    'ก่อนหน้านี้ระบบได้รับข้อมูลลงทะเบียนไว้เรียบร้อยแล้วนะคะ 😊',
    '',
    'หากต้องการกรอกข้อมูลใหม่ พิมพ์ “เริ่มใหม่”',
    'หากต้องการให้เจ้าหน้าที่ช่วยดูแลต่อ พิมพ์ “ติดต่อเจ้าหน้าที่” ได้เลยค่ะ'
  ].join('\n');
}

let consent_decision = null;
let needs_field_validation = false;

if ((current_state === 'handover_to_staff' || current_state === 'completed') && is_registration_completed) {
  consent_decision = {
    action: 'post_completion_options',
    nextState: 'handover_to_staff',
    consentStatus: consent_status,
    replyText: PostCompletionOptionsText()
  };
} else if (current_state === 'handover_to_staff' || current_state === 'completed') {
  consent_decision = {
    action: 'silent_handover',
    nextState: 'handover_to_staff',
    consentStatus: consent_status,
    replyText: ''
  };
} else if (item.eventType === 'follow') {
  consent_decision = {
    action: 'ask_consent',
    nextState: 'waiting_consent',
    consentStatus: 'pending',
    replyText: ConsentIntroText()
  };
} else if (current_state === 'waiting_consent' || consent_status !== 'accepted') {
  // ต้องเช็คไม่ยินยอมก่อน เพราะคำว่า “ไม่ยินยอม” มีคำว่า “ยินยอม” อยู่ข้างใน
  if (IsConsentDecline()) {
    consent_decision = {
      action: 'decline_consent',
      nextState: 'consent_declined',
      consentStatus: 'declined',
      replyText: 'เข้าใจค่ะ 😊\nตอนนี้บอทจะยังไม่เก็บข้อมูลส่วนตัวนะคะ\n\nหากต้องการเริ่มลงทะเบียนใหม่ สามารถพิมพ์ “ยินยอม” ได้เลย\nหรือพิมพ์ “ติดต่อเจ้าหน้าที่” เพื่อให้ทีมงานเข้ามาดูแลต่อค่ะ'
    };
  } else if (IsConsentAccept()) {
    consent_decision = {
      action: 'accept_consent',
      nextState: 'waiting_parent_name',
      consentStatus: 'accepted',
      replyText: 'ขอบคุณค่ะ 😊\n' + questions.waiting_parent_name
    };
  } else {
    consent_decision = {
      action: 'ask_consent',
      nextState: 'waiting_consent',
      consentStatus: 'pending',
      replyText: ConsentIntroText()
    };
  }
} else if (current_state === 'consent_declined') {
  consent_decision = {
    action: 'consent_declined_idle',
    nextState: 'consent_declined',
    consentStatus: 'declined',
    replyText: 'ตอนนี้บอทยังไม่เก็บข้อมูลส่วนตัวนะคะ 😊\nหากต้องการเริ่มลงทะเบียน สามารถพิมพ์ “ยินยอม” หรือพิมพ์ “ติดต่อเจ้าหน้าที่” ได้เลยค่ะ'
  };
} else {
  needs_field_validation = true;
}

return {
  json: {
    ...item,
    questions,
    consentDecision: consent_decision,
    needsFieldValidation: needs_field_validation
  }
};

const item = $json || {};
const text = NormalizeText(item.normalizedText || item.messageText || '');
const state = item.conversationState;
const questions = item.questions || {};
const current_student_index = Number(item.currentStudentIndex || 0);

function NormalizeText(value) {
  return String(value || '').trim().replace(/\s+/g, ' ');
}

function NormalizeThaiDigits(value) {
  const thai_digit_by_arabic_digit = {
    '๐': '0',
    '๑': '1',
    '๒': '2',
    '๓': '3',
    '๔': '4',
    '๕': '5',
    '๖': '6',
    '๗': '7',
    '๘': '8',
    '๙': '9'
  };
  return String(value || '').replace(/[๐-๙]/g, (digit) => thai_digit_by_arabic_digit[digit] || digit);
}

function LowerText(value) {
  return NormalizeThaiDigits(value).toLowerCase();
}

function CreatePass(normalized_value, reason) {
  return {
    status: 'pass',
    normalizedValue: normalized_value,
    reason: reason || 'rule_pass'
  };
}

function CreateFail(reply_text, reason, count_invalid = true) {
  return {
    status: 'fail',
    normalizedValue: '',
    replyText: reply_text,
    reason: reason || 'rule_fail',
    countInvalid: count_invalid
  };
}

function CreateNeedsAi(reason) {
  return {
    status: 'needs_ai',
    reason: reason || 'ambiguous_rule_result'
  };
}

function IncludesAny(lower_text, keywords) {
  return keywords.some((keyword) => lower_text.includes(String(keyword).toLowerCase()));
}

function EqualsAny(lower_text, keywords) {
  return keywords.some((keyword) => lower_text === String(keyword).toLowerCase());
}

function HasLetter(value) {
  return /[A-Za-zก-๙]/.test(value);
}

function LooksLikePhone(value) {
  const phone_text = NormalizeThaiDigits(value).replace(/[\s\-().]/g, '');
  return /^(\+66|0)?[0-9]{8,12}$/.test(phone_text);
}

function LooksLikeGrade(value) {
  const lower_text = LowerText(value)
    .replace(/\s+/g, '')
    .replace(/ปี/g, '')
    .replace(/ศึกษา/g, '')
    .replace(/ที่/g, '');
  return /^(อ\.?|อนุบาล|ป\.?|ประถม|ม\.?|มัธยม|p|m)[0-9]+$/.test(lower_text);
}

function IsProbablyUrlOrHandle(value) {
  const lower_text = LowerText(value);
  return /(https?:\/\/|www\.|@|line\s?id|ไลน์\s?id)/i.test(lower_text);
}

function BuildNameRetryReply(field_type) {
  if (field_type === 'parent_name') {
    return 'รบกวนขอชื่อหรือชื่อเล่นของคุณพ่อ/คุณแม่เพิ่มเติมนิดนึงนะคะ 😊 เช่น แม่ก้อย หรือคุณพ่อนัทค่ะ';
  }

  return [
    'รบกวนขอชื่อน้องหรือชื่อเล่นน้องอีกครั้งนะคะ 😊',
    'เช่น น้องมีนา, น้องต้น หรือ น้องแพรค่ะ'
  ].join('\n');
}

function ValidatePersonName(value, field_type) {
  const normalized_value = NormalizeText(value);
  const lower_text = LowerText(normalized_value);
  const compact_text = lower_text.replace(/\s+/g, '');

  const common_invalid_exact_keywords = [
    '', 'ค่ะ', 'ครับ', 'คะ', 'จ้า', 'จ่ะ', 'ฮะ', 'โอเค', 'ok', 'okay', 'ได้ค่ะ', 'ได้ครับ',
    'สวัสดี', 'หวัดดี', 'hello', 'hi', '555', '5555', '55555', 'test', 'ทดสอบ',
    'ไม่บอก', 'ยังไม่บอก', 'ไม่ค่ะ', 'ไม่ครับ', 'ไม่คะ', 'ไม่จ้า', 'ไม่รู้', 'ไม่ทราบ',
    'ยังไม่รู้', 'ยังไม่ทราบ', 'ไม่มี', 'ไม่เอา', 'ขอผ่าน', 'ผ่านก่อน', 'เราเอง', 'ฉันเอง',
    'คนเดิม', 'เบอร์เดิม', '-', '.', '/', 'na', 'n/a'
  ];

  const common_invalid_phrase_keywords = [
    'ไม่รู้', 'ไม่ทราบ', 'ไม่บอก', 'ยังไม่บอก', 'จำไม่ได้', 'ขอผ่าน', 'ผ่านก่อน',
    'ไม่มีชื่อ', 'ยังไม่ได้ตั้งชื่อ', 'ไม่ให้ชื่อ', 'ไม่สะดวกให้ชื่อ', 'ทดสอบ', 'test',
    'asdf', 'qwer', 'qwerty', 'xxx', 'yyy', 'zzz', '1234'
  ];

  if (EqualsAny(lower_text, common_invalid_exact_keywords) || IncludesAny(lower_text, common_invalid_phrase_keywords)) {
    return CreateFail(BuildNameRetryReply(field_type), `${field_type}_common_invalid`, true);
  }

  if (LooksLikePhone(normalized_value)) {
    const reply_text = field_type === 'parent_name'
      ? 'ตอนนี้บอทขอชื่อผู้ปกครองก่อนนะคะ 😊 รบกวนแจ้งชื่อหรือชื่อเล่น เช่น แม่ก้อย หรือคุณพ่อนัทค่ะ'
      : 'ตอนนี้บอทขอชื่อน้องก่อนนะคะ 😊 รบกวนแจ้งชื่อน้องหรือชื่อเล่นน้องค่ะ';
    return CreateFail(reply_text, `${field_type}_looks_like_phone`, false);
  }

  if (LooksLikeGrade(normalized_value)) {
    const reply_text = field_type === 'parent_name'
      ? 'ตอนนี้บอทขอชื่อผู้ปกครองก่อนนะคะ 😊 รบกวนแจ้งชื่อหรือชื่อเล่น เช่น แม่ก้อย หรือคุณพ่อนัทค่ะ'
      : 'ตอนนี้บอทขอชื่อน้องก่อนนะคะ 😊 ระดับชั้นจะถามในขั้นถัดไปค่ะ';
    return CreateFail(reply_text, `${field_type}_looks_like_grade`, false);
  }

  if (IsProbablyUrlOrHandle(normalized_value)) {
    const reply_text = field_type === 'parent_name'
      ? 'รบกวนแจ้งเป็นชื่อหรือชื่อเล่นของผู้ปกครองแทนลิงก์หรือไอดีนะคะ 😊'
      : 'รบกวนแจ้งเป็นชื่อน้องหรือชื่อเล่นน้องแทนลิงก์หรือไอดีนะคะ 😊';
    return CreateFail(reply_text, `${field_type}_url_or_handle`, true);
  }

  if (field_type === 'parent_name') {
    const role_only_keywords = ['แม่', 'คุณแม่', 'พ่อ', 'คุณพ่อ', 'ผู้ปกครอง', 'ผปค', 'พ่อแม่', 'ผู้ดูแล'];
    if (EqualsAny(lower_text, role_only_keywords)) {
      return CreateFail(
        'รบกวนขอชื่อหรือชื่อเล่นเพิ่มเติมนิดนึงนะคะ 😊 เช่น แม่ก้อย, คุณพ่อนัท หรือคุณแม่แอนค่ะ',
        'parent_name_role_only',
        false
      );
    }
  }

  if (field_type === 'student_name') {
    const student_invalid_exact_keywords = [
      'ไวๆ', 'เร็วๆ', 'รีบๆ', 'วัยรุ่น', 'เด็ก', 'ลูก', 'น้อง', 'ชื่อเล่น', 'ชื่อ',
      'โตแล้ว', 'เด็กเล็ก', 'ผู้ชาย', 'ผู้หญิง', 'อะไรก็ได้', 'ชื่ออะไรก็ได้',
      'แล้วแต่', 'ตามใจ', 'มั่ว', 'มั่วๆ', 'มั่วๆไป', 'เล่นๆ', 'ล้อเล่น', 'กดเล่น',
      'เร็ว', 'ไว', 'รีบ', 'ไม่ค่ะ', 'ไม่ครับ', 'ไม่คะ', 'ไม่มี', 'ไม่บอก', 'ขอผ่าน', 'ผ่านก่อน'
    ];

    const student_invalid_phrase_keywords = [
      'มั่ว', 'เล่นๆ', 'ล้อเล่น', 'อะไรก็ได้', 'ชื่ออะไรก็ได้', 'ไม่ใช่ชื่อ',
      'ไม่มีชื่อ', 'ยังไม่ได้ตั้งชื่อ', 'ไม่รู้ชื่อ', 'ไม่ทราบชื่อ', 'จำชื่อไม่ได้',
      'ขอไม่บอก', 'ไม่บอกชื่อ', 'กดเล่น', 'ตอบเล่น', 'ตอบมั่ว', 'เร็วๆ', 'ไวๆ', 'รีบๆ'
    ];

    const student_sentence_like_keywords = [
      'ชื่ออะไร', 'ถามทำไม', 'เอาไปทำไม', 'ไม่อยาก', 'ไม่สะดวก', 'ไม่ให้', 'เดี๋ยวบอก'
    ];

    if (
      EqualsAny(lower_text, student_invalid_exact_keywords)
      || IncludesAny(lower_text, student_invalid_phrase_keywords)
      || IncludesAny(lower_text, student_sentence_like_keywords)
    ) {
      return CreateFail(BuildNameRetryReply(field_type), 'student_name_invalid_or_random_answer', true);
    }

    if (/[0-9๐-๙]/.test(normalized_value)) {
      return CreateFail('ตอนนี้บอทขอชื่อน้องก่อนนะคะ 😊 รบกวนแจ้งเป็นชื่อหรือชื่อเล่นน้อง ไม่ใช่ตัวเลขค่ะ', 'student_name_contains_number', false);
    }

    if (/[ๆ!?！？#*_={}\[\]<>|\\/]/.test(normalized_value)) {
      return CreateFail(BuildNameRetryReply(field_type), 'student_name_contains_suspicious_symbol', true);
    }

    if (normalized_value.length > 30) {
      return CreateNeedsAi('student_name_long_or_sentence_like');
    }
  }

  if (!HasLetter(normalized_value) || normalized_value.length > 40) {
    const reply_text = field_type === 'parent_name'
      ? 'รบกวนแจ้งชื่อหรือชื่อเล่นของผู้ปกครองอีกครั้งนะคะ 😊'
      : BuildNameRetryReply(field_type);
    return CreateFail(reply_text, `${field_type}_invalid_shape`, true);
  }

  if (normalized_value.length <= 1 && field_type === 'parent_name') {
    return CreateNeedsAi('parent_name_too_short_for_rule');
  }

  if (field_type === 'student_name' && normalized_value.length <= 1) {
    return CreateFail(BuildNameRetryReply(field_type), 'student_name_too_short', false);
  }

  return CreatePass(normalized_value, `${field_type}_rule_pass`);
}

function ValidatePhone(value) {
  const lower_text = LowerText(value);
  const invalid_keywords = ['เบอร์เดิม', 'โทรมาเลย', 'ไม่มี', 'ไม่บอก', 'ยังไม่ให้', 'ไม่ให้เบอร์', 'ไม่สะดวกให้เบอร์'];

  if (EqualsAny(lower_text, invalid_keywords) || IncludesAny(lower_text, ['ไม่ให้เบอร์', 'ไม่บอกเบอร์'])) {
    return CreateFail('รบกวนขอเบอร์มือถือที่สะดวกให้ทีมงานติดต่อกลับนะคะ 😊', 'phone_refused_or_missing', true);
  }

  const compact_phone = NormalizeThaiDigits(value).replace(/[\s\-().]/g, '');
  let normalized_value = '';

  if (/^\+66[689][0-9]{8}$/.test(compact_phone)) {
    normalized_value = '0' + compact_phone.slice(3);
  } else if (/^66[689][0-9]{8}$/.test(compact_phone)) {
    normalized_value = '0' + compact_phone.slice(2);
  } else if (/^0[689][0-9]{8}$/.test(compact_phone)) {
    normalized_value = compact_phone;
  }

  if (!normalized_value) {
    return CreateFail('รบกวนขอเบอร์มือถือ 10 หลัก เช่น 0812345678 นะคะ 😊', 'phone_invalid_format', true);
  }

  if (/^([0-9])\1+$/.test(normalized_value)) {
    return CreateFail('รบกวนขอเบอร์มือถือที่ถูกต้องอีกครั้งนะคะ 😊', 'phone_repeated_digits', true);
  }

  return CreatePass(normalized_value, 'phone_rule_pass');
}

function ValidateStudentCount(value) {
  const raw_text = NormalizeThaiDigits(NormalizeText(value));
  const lower_text = LowerText(raw_text).replace(/\s+/g, '');

  const thai_number_map = {
    'หนึ่ง': 1,
    'นึง': 1,
    'คนนึง': 1,
    'คนหนึ่ง': 1,
    'คนเดียว': 1,
    'ลูกคนเดียว': 1,
    'เดียว': 1,
    'สอง': 2,
    'สองคน': 2,
    'สาม': 3,
    'สามคน': 3,
    'สี่': 4,
    'สี่คน': 4
  };

  for (const [keyword, number] of Object.entries(thai_number_map)) {
    if (lower_text.includes(keyword)) {
      return CreatePass(number, 'student_count_thai_word_rule_pass');
    }
  }

  const number_match = lower_text.match(/[1-4]/);
  if (!number_match) {
    return CreateFail(
      'รบกวนแจ้งจำนวนเป็น 1-4 คนนะคะ เช่น 1 คน, 2 คน หรือพิมพ์ว่า คนเดียว ก็ได้ค่ะ',
      'student_count_not_found',
      false
    );
  }

  const count = Number(number_match[0]);
  if (count < 1 || count > 4) {
    return CreateFail(
      'ตอนนี้ระบบรองรับการลงทะเบียนน้อง 1-4 คนนะคะ รบกวนแจ้งจำนวนอีกครั้งค่ะ',
      'student_count_out_of_range',
      false
    );
  }

  return CreatePass(count, 'student_count_rule_pass');
}

function ValidateStudentGrade(value) {
  const normalized_text = NormalizeThaiDigits(value);
  const original_compact_text = LowerText(normalized_text).replace(/\s+/g, '');
  const compact_text = original_compact_text
    .replace(/ปี/g, '')
    .replace(/ศึกษา/g, '')
    .replace(/ที่/g, '');
  const broad_grade_keywords = ['อนุบาล', 'ประถม', 'มัธยม', 'เด็กเล็ก', 'โตแล้ว', 'วัยรุ่น'];
  const ineligible_reply_text = [
    'ขออภัยค่ะ ตอนนี้ eiMaths เปิดรับน้องอายุ 3–12 ปี หรือระดับชั้นอนุบาล 1 ถึง ป.6 เท่านั้นนะคะ 😊',
    'หากต้องการให้เจ้าหน้าที่ช่วยดูรายละเอียดเพิ่มเติม สามารถพิมพ์ “ติดต่อเจ้าหน้าที่” ได้เลยค่ะ'
  ].join('\n');

  function BuildGrade(prefix, raw_level) {
    const level = Number(raw_level);
    if (prefix === 'อ' && level >= 1 && level <= 3) return `อ.${level}`;
    if (prefix === 'ป' && level >= 1 && level <= 6) return `ป.${level}`;
    return '';
  }

  const secondary_grade_match = compact_text.match(/^(?:ม\.?|มัธยม|m)([0-9]+)$/);
  if (secondary_grade_match) {
    return CreateFail(ineligible_reply_text, 'student_grade_secondary_not_eligible', false);
  }

  const kindergarten_grade_match = compact_text.match(/^(?:อ\.?|อนุบาล)([0-9]+)$/);
  if (kindergarten_grade_match) {
    const kindergarten_level = Number(kindergarten_grade_match[1]);
    const normalized_value = BuildGrade('อ', kindergarten_grade_match[1]);
    if (normalized_value) return CreatePass(normalized_value, 'student_grade_rule_pass');
    if (kindergarten_level > 3 || kindergarten_level < 1) {
      return CreateFail(ineligible_reply_text, 'student_grade_kindergarten_not_eligible', false);
    }
  }

  const primary_grade_match = compact_text.match(/^(?:ป\.?|ประถม|p)([0-9]+)$/);
  if (primary_grade_match) {
    const primary_level = Number(primary_grade_match[1]);
    const normalized_value = BuildGrade('ป', primary_grade_match[1]);
    if (normalized_value) return CreatePass(normalized_value, 'student_grade_rule_pass');
    if (primary_level > 6 || primary_level < 1) {
      return CreateFail(ineligible_reply_text, 'student_grade_primary_not_eligible', false);
    }
  }

  const age_match = original_compact_text.match(/(?:อายุ)?([0-9]{1,2})(?:ขวบ|ปี|yrs?|years?)/i);
  if (age_match) {
    const age_years = Number(age_match[1]);
    if (age_years >= 3 && age_years <= 12) {
      return CreateFail('รบกวนแจ้งเป็นระดับชั้นของน้องด้วยนะคะ 😊 เช่น อนุบาล 1, ป.1 หรือ ป.6 ค่ะ', 'student_grade_age_without_grade', false);
    }
    return CreateFail(ineligible_reply_text, 'student_age_not_eligible', false);
  }

  if (compact_text === 'มัธยม' || compact_text.startsWith('มัธยม') || compact_text === 'ม') {
    return CreateFail(ineligible_reply_text, 'student_grade_secondary_broad_not_eligible', false);
  }

  if (EqualsAny(compact_text, broad_grade_keywords) || broad_grade_keywords.some((keyword) => compact_text === keyword)) {
    return CreateFail('รบกวนแจ้งระดับชั้นพร้อมเลขชั้นด้วยนะคะ 😊 เช่น อนุบาล 1, ป.1 หรือ ป.6 ค่ะ', 'student_grade_missing_level', false);
  }

  return CreateFail('รบกวนแจ้งระดับชั้นให้ชัดเจน เช่น อนุบาล 1, ป.1 หรือ ป.6 นะคะ 😊', 'student_grade_invalid_format', true);
}

function ValidatePainPoint(value) {
  const normalized_value = NormalizeText(value);
  const lower_text = LowerText(normalized_value);

  const short_clarification_keywords = ['กลัว', 'ไม่ชอบ', 'ไม่เข้าใจ', 'ทำไม่ได้', 'ยาก', 'อ่อน', 'ไม่เก่ง'];
  const useful_problem_keywords = [
    'คณิต', 'เลข', 'โจทย์', 'เรียนไม่ทัน', 'ไม่ทัน', 'กลัวเลข', 'กลัวคณิต',
    'ไม่เข้าใจ', 'ไม่ชอบ', 'ทำโจทย์', 'ทำไม่ได้', 'ช้า', 'พื้นฐาน', 'สอบ',
    'คะแนน', 'เพิ่มความมั่นใจ', 'มั่นใจ', 'เกรด', 'สมาธิ', 'ท่องสูตร', 'บวก', 'ลบ', 'คูณ', 'หาร'
  ];
  const invalid_keywords = ['', 'ok', 'okay', 'โอเค', 'ค่ะ', 'ครับ', 'คะ', '555', 'แล้วแต่', 'อะไรก็ได้', 'ไม่รู้', 'ยังไม่รู้'];

  if (EqualsAny(lower_text, invalid_keywords)) {
    return CreateFail(
      'รบกวนเล่าเพิ่มเติมนิดนึงนะคะว่าอยากให้ eiMaths ช่วยน้องเรื่องไหนเป็นพิเศษ 😊',
      'pain_point_invalid_short',
      true
    );
  }

  if (EqualsAny(lower_text, short_clarification_keywords)) {
    return CreateFail(
      'ขอรายละเอียดเพิ่มนิดนึงนะคะ 😊 เช่น กลัว/ไม่ชอบ/ไม่เข้าใจเรื่องไหน หรืออยากให้ช่วยด้านไหนเป็นพิเศษคะ',
      'pain_point_needs_clarification',
      false
    );
  }

  if (IncludesAny(lower_text, useful_problem_keywords) && normalized_value.length >= 5) {
    return CreatePass(normalized_value, 'pain_point_rule_pass');
  }

  return CreateNeedsAi('pain_point_ambiguous');
}

function ValidatePreferredContactTime(value) {
  const normalized_value = NormalizeText(value);
  const lower_text = LowerText(normalized_value);

  const now_keywords = ['ตอนนี้', 'ตอนนี้เลย', 'โทรได้เลย', 'เดี๋ยวนี้', 'สะดวกตอนนี้', 'ตอนนี้ได้', 'โทรมาได้เลย'];
  const unavailable_keywords = ['ไม่สะดวก', 'ยังไม่สะดวก', 'ไม่ว่าง', 'ยังไม่รู้', 'เดี๋ยวบอก', 'ไม่รู้', 'ไว้ก่อน'];
  const time_keywords = [
    'เช้า', 'สาย', 'บ่าย', 'เย็น', 'ค่ำ', 'กลางวัน', 'หลังเลิกงาน', 'หลังเลิกเรียน',
    'วันนี้', 'พรุ่งนี้', 'มะรืน', 'เสาร์', 'อาทิตย์', 'วันหยุด', 'ทุกวัน', 'ได้ตลอด',
    'หลัง', 'ก่อน', 'ช่วง'
  ];

  if (EqualsAny(lower_text, now_keywords) || IncludesAny(lower_text, now_keywords)) {
    return CreatePass('ตอนนี้', 'preferred_contact_time_now_rule_pass');
  }

  if (EqualsAny(lower_text, unavailable_keywords) || IncludesAny(lower_text, unavailable_keywords)) {
    return CreateFail(
      'พอมีช่วงไหนที่สะดวกให้ทีมงานติดต่อกลับไหมคะ 😊 เช่น หลัง 18:00 หรือพรุ่งนี้บ่ายค่ะ',
      'preferred_contact_time_unavailable',
      false
    );
  }

  if (/\b([01]?[0-9]|2[0-3])[:.][0-5][0-9]\b/.test(lower_text) || /\b([01]?[0-9]|2[0-3])\s*(โมง|น\.|am|pm)\b/i.test(lower_text)) {
    return CreatePass(normalized_value, 'preferred_contact_time_clock_rule_pass');
  }

  if (IncludesAny(lower_text, time_keywords) && normalized_value.length >= 2) {
    return CreatePass(normalized_value, 'preferred_contact_time_keyword_rule_pass');
  }

  return CreateNeedsAi('preferred_contact_time_ambiguous');
}

function ValidateByState(current_state, value) {
  const validation_by_state = {
    waiting_parent_name: () => ValidatePersonName(value, 'parent_name'),
    waiting_phone: () => ValidatePhone(value),
    waiting_student_count: () => ValidateStudentCount(value),
    waiting_student_name: () => ValidatePersonName(value, 'student_name'),
    waiting_student_grade: () => ValidateStudentGrade(value),
    waiting_pain_point: () => ValidatePainPoint(value),
    waiting_preferred_contact_time: () => ValidatePreferredContactTime(value)
  };

  const validator = validation_by_state[current_state];
  if (!validator) return CreateNeedsAi('unknown_state');
  return validator();
}

const hybrid_validation = ValidateByState(state, text);
const should_use_ai_validation = hybrid_validation.status === 'needs_ai';

const ai_validation_request = {
  current_state: state,
  expected_question: questions[state] || '',
  current_student_index,
  user_message: text,
  existing_answers: item.existingAnswers || {},
  consent_status: item.consentStatus || 'accepted',
  validation_mode: 'hybrid_rule_first_ai_for_ambiguous_fields',
  rule_result: hybrid_validation,
  note: should_use_ai_validation
    ? 'Rule validator could not make a safe decision. AI should validate this field without guessing missing data.'
    : 'Rule validator already made a deterministic decision. AI is skipped.'
};

return {
  json: {
    ...item,
    ruleValidation: should_use_ai_validation ? null : hybrid_validation,
    shouldUseAiValidation: should_use_ai_validation,
    aiValidationRequest: ai_validation_request,
    aiFallbackReplyText: questions[state] || 'รบกวนตอบข้อมูลส่วนนี้อีกครั้งนะคะ 😊',
    hybridValidation: hybrid_validation
  }
};

const source_item = $('Prepare AI Validation Request').item.json;

function BuildFallbackReplyText() {
  return source_item.aiFallbackReplyText
    || source_item.questions?.[source_item.conversationState]
    || 'ขออภัยค่ะ ตอนนี้ระบบตรวจคำตอบอัตโนมัติไม่พร้อมใช้งานชั่วคราว รบกวนพิมพ์คำตอบนี้อีกครั้งนะคะ 😊';
}

let ai_validation = {
  is_valid: false,
  confidence: 0,
  detected_intent: 'ask_clarification',
  normalized_value: '',
  reason: 'AI Agent did not return a usable JSON response',
  reply_text: BuildFallbackReplyText()
};

function ExtractJsonText(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') {
    if (value.error || value.message) {
      const error_message = value.error?.message || value.error || value.message || 'AI Agent error';
      throw new Error(String(error_message));
    }
    if (typeof value.output === 'string') return value.output;
    if (typeof value.text === 'string') return value.text;
    if (typeof value.response === 'string') return value.response;
    if (typeof value.result === 'string') return value.result;
    if (typeof value.content === 'string') return value.content;
    return JSON.stringify(value);
  }
  return String(value);
}

function ParseJsonObject(raw_value) {
  const raw_text = ExtractJsonText(raw_value).trim();
  if (!raw_text) throw new Error('empty AI Agent output');

  try {
    return JSON.parse(raw_text);
  } catch (direct_error) {
    const match = raw_text.match(/\{[\s\S]*\}/);
    if (!match) throw direct_error;
    return JSON.parse(match[0]);
  }
}

try {
  const parsed = ParseJsonObject($json);
  if (parsed && typeof parsed === 'object') {
    const confidence = Number(parsed.confidence || 0);
    ai_validation = {
      is_valid: Boolean(parsed.is_valid) && confidence >= 0.75,
      confidence,
      detected_intent: String(parsed.detected_intent || 'unknown'),
      normalized_value: String(parsed.normalized_value || ''),
      reason: String(parsed.reason || ''),
      reply_text: String(parsed.reply_text || '')
    };
  }
} catch (error) {
  ai_validation.reason = `AI Agent unavailable or JSON parse failed: ${error.message}`;
  ai_validation.reply_text = BuildFallbackReplyText();
}

return {
  json: {
    ...source_item,
    aiValidation: ai_validation,
    aiAgentRawOutput: $json
  }
};

const item = $json || {};
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};

const now_iso = item.nowIso || new Date().toISOString();
const line_user_id = item.lineUserId;
const questions = item.questions || {
