  waiting_phone: 'ขอเบอร์โทรที่สะดวกให้ทีมงานติดต่อกลับหน่อยนะคะ',
  waiting_student_count: 'ต้องการลงทะเบียนทดลองเรียนฟรีให้น้องกี่คนคะ 😊\nพิมพ์ได้เลย เช่น 1 คน, 2 คน หรือ คนเดียวค่ะ',
  waiting_student_name: 'น้องชื่ออะไรคะ จะได้ให้ทีมงานเรียกชื่อน้องถูกค่ะ 😊',
  waiting_student_grade: 'ตอนนี้น้องอยู่ระดับชั้นไหนคะ เช่น อนุบาล 1, ป.1 หรือ ป.6',
  waiting_pain_point: `ตอนนี้อยากให้ eiMaths ช่วยน้องเรื่องไหนเป็นพิเศษคะ\nเช่น ไม่ชอบคณิต, กลัวเลข, ทำโจทย์ไม่ค่อยได้, เรียนไม่ทัน หรืออยากเพิ่มความมั่นใจ`,
  waiting_preferred_contact_time: `คุณพ่อ/คุณแม่สะดวกให้ทีมงานติดต่อกลับช่วงเวลาไหนคะ\nเช่น หลัง 18:00 หรือช่วงเย็นหลังเลิกงาน`
};

function CreateDefaultConversation() {
  return {
    state: 'waiting_consent',
    consentStatus: 'pending',
    answers: {},
    createdAt: now_iso,
    startedAt: now_iso,
    followedAt: item.eventType === 'follow' ? now_iso : null,
    lastMessageAt: now_iso,
    invalidCountByState: {},
    totalInvalidCount: 0,
    handoverReplyCount: 0,
    postCompletionReplyCount: 0,
    handoverNotifiedAt: null,
    handoverReason: null,
    completedAt: null,
    aiValidationSummary: [],
    currentStudentIndex: 0
  };
}

function MoveToNextState(current_state, conversation) {
  const next_state_by_current_state = {
    waiting_parent_name: 'waiting_phone',
    waiting_phone: 'waiting_student_count',
    waiting_student_count: 'waiting_student_name',
    waiting_student_name: 'waiting_student_grade',
    waiting_student_grade: 'waiting_pain_point',
    waiting_preferred_contact_time: 'ready_to_submit_crm'
  };

  if (current_state === 'waiting_pain_point') {
    const current_index = Number(conversation.currentStudentIndex || 0);
    const student_count = Number(conversation.answers.student_count || 1);
    if (current_index + 1 < student_count) {
      conversation.currentStudentIndex = current_index + 1;
      return 'waiting_student_name';
    }
    return 'waiting_preferred_contact_time';
  }

  return next_state_by_current_state[current_state] || 'handover_to_staff';
}

function AnswerKeyForState(current_state) {
  const answer_key_by_state = {
    waiting_parent_name: 'parent_name',
    waiting_phone: 'phone',
    waiting_student_count: 'student_count',
    waiting_preferred_contact_time: 'preferred_contact_time'
  };
  return answer_key_by_state[current_state] || null;
}

function EnsureStudents(conversation) {
  conversation.answers.students = Array.isArray(conversation.answers.students) ? conversation.answers.students : [];
  const index = Number(conversation.currentStudentIndex || 0);
  conversation.answers.students[index] = conversation.answers.students[index] || {};
  return conversation.answers.students[index];
}

function StoreAnswerForState(conversation, current_state, normalized_value) {
  if (current_state === 'waiting_student_count') {
    const count = Math.max(1, Math.min(4, Number(normalized_value || 1)));
    conversation.answers.student_count = count;
    conversation.answers.students = [];
    conversation.currentStudentIndex = 0;
    return;
  }

  if (current_state === 'waiting_student_name') {
    EnsureStudents(conversation).student_name = normalized_value;
    return;
  }

  if (current_state === 'waiting_student_grade') {
    EnsureStudents(conversation).student_grade = normalized_value;
    return;
  }

  if (current_state === 'waiting_pain_point') {
    EnsureStudents(conversation).pain_point = normalized_value;
    return;
  }

  const answer_key = AnswerKeyForState(current_state);
  if (answer_key) conversation.answers[answer_key] = normalized_value;
}

function GetCurrentStudent(conversation) {
  conversation.answers = conversation.answers || {};
  conversation.answers.students = Array.isArray(conversation.answers.students)
    ? conversation.answers.students
    : [];

  const index = Number(conversation.currentStudentIndex || 0);
  return conversation.answers.students[index] || {};
}

function GetStudentDisplayName(conversation) {
  const student = GetCurrentStudent(conversation);
  const name = String(student.student_name || '').trim();

  if (!name) return 'น้อง';
  if (name.startsWith('น้อง')) return name;
  return 'น้อง' + name;
}

function QuestionForState(state, conversation) {
  const index = Number(conversation.currentStudentIndex || 0);
  const student_count = Number(conversation.answers?.student_count || 1);
  const student_label = GetStudentDisplayName(conversation);

  if (state === 'waiting_student_name') {
    if (student_count <= 1) {
      return 'น้องชื่ออะไรคะ 😊';
    }

    if (index === 0) {
      return 'ขอข้อมูลน้องคนที่ 1 นะคะ 😊 น้องชื่ออะไรคะ';
    }

    return 'ต่อไปขอข้อมูลน้องคนที่ ' + (index + 1) + ' นะคะ 😊 น้องชื่ออะไรคะ';
  }

  if (state === 'waiting_student_grade') {
    if (student_count <= 1) {
      return student_label + 'อยู่ระดับชั้นไหนคะ เช่น อนุบาล 1, ป.1 หรือ ป.6';
    }

    return student_label + 'อยู่ระดับชั้นไหนคะ เช่น อนุบาล 1, ป.1 หรือ ป.6';
  }

  if (state === 'waiting_pain_point') {
    if (student_count <= 1) {
      return 'อยากให้ eiMaths ช่วย' + student_label + 'เรื่องไหนเป็นพิเศษคะ เช่น ไม่ชอบคณิต กลัวเลข เรียนไม่ทัน หรืออยากเพิ่มความมั่นใจ';
    }

    return 'อยากให้ eiMaths ช่วย' + student_label + 'เรื่องไหนเป็นพิเศษคะ เช่น ไม่ชอบคณิต กลัวเลข เรียนไม่ทัน หรืออยากเพิ่มความมั่นใจ';
  }

  return questions[state] || 'ขอบคุณค่ะ';
}

function BuildConsentIntroText() {
  return [
    'ได้เลยค่ะ เริ่มลงทะเบียนใหม่ให้นะคะ 😊',
    '',
    'ก่อนเริ่ม ขออนุญาตเก็บข้อมูลเบื้องต้นเพื่อให้ทีมงานติดต่อกลับและแนะนำคลาสทดลองเรียนฟรีค่ะ',
    '',
    'หากยินยอมให้เก็บข้อมูล พิมพ์ “ยินยอม”',
    'หากยังไม่สะดวกให้เก็บข้อมูล พิมพ์ “ไม่ยินยอม”',
    'หรือพิมพ์ “ติดต่อเจ้าหน้าที่” เพื่อให้ทีมงานดูแลต่อค่ะ'
  ].join('\n');
}

function BuildRegistrationBatchId() {
  const safe_line_id = String(line_user_id || 'lead').replace(/[^a-zA-Z0-9_-]/g, '').slice(-16) || 'lead';
  return 'line_restart_' + safe_line_id + '_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
}

function BuildCrmPayload(conversation) {
  const student_count = Number(conversation.answers.student_count || 1);
  const students = (Array.isArray(conversation.answers.students) ? conversation.answers.students.slice(0, student_count) : []).map((student) => ({
    student_name: student.student_name || null,
    student_grade: student.student_grade || null,
    student_school: student.student_school || null,
    student_age: student.student_age || null,
    pain_point: student.pain_point || null
  }));
  const first_student = students[0] || {};
  conversation.registrationBatchId = conversation.registrationBatchId || BuildRegistrationBatchId();
  return {
    ...conversation.answers,
    student_name: first_student.student_name || conversation.answers.student_name || null,
    student_grade: first_student.student_grade || conversation.answers.student_grade || null,
    pain_point: first_student.pain_point || conversation.answers.pain_point || null,
    student_count,
    students,
    is_restart_flow: Boolean(conversation.isRestartFlow),
    registration_batch_id: conversation.registrationBatchId,
    interest: 'ทดลองเรียนฟรี 2 คลาส',
    consent_status: conversation.consentStatus || 'accepted',
    consent_accepted_at: conversation.consentAcceptedAt || null,
    ai_validation_summary: conversation.aiValidationSummary || [],
    invalid_attempt_count: conversation.totalInvalidCount || 0,
    handover_reason: conversation.handoverReason || null,
    line_user_id: line_user_id,
    line_display_name: conversation.displayName || item.displayName || null,
    line_picture_url: conversation.pictureUrl || item.pictureUrl || null,
    line_follow_status: 'followed',
    line_followed_at: conversation.followedAt || now_iso,
    line_last_message_at: now_iso,
    line_conversation_state: 'completed',
    line_source: 'new_customer_line_oa',
    utm_source: 'line',
    utm_medium: 'new_customer_oa_chat',
    utm_campaign: 'unknown',
    utm_content: null,
    first_touch_source: 'line',
    last_touch_source: 'new_customer_line_oa',
    created_from: 'new_customer_line_oa_chatbot',
    lead_status: 'new_lead'
  };
}

function BuildHandoverNotificationText(conversation, reason) {
  const answers = conversation.answers || {};
  return [
    '⚠️ ต้องการเจ้าหน้าที่ช่วยดูแล',
    '',
    `เหตุผล: ${reason || conversation.handoverReason || '-'}`,
    `LINE: ${conversation.displayName || item.displayName || '-'}`,
    `LINE User ID: ${line_user_id || '-'}`,
    `State ล่าสุด: ${conversation.state || '-'}`,
    `ข้อความล่าสุด: ${item.normalizedText || '-'}`,
    '',
    'ข้อมูลที่เก็บได้แล้ว:',
    `ผู้ปกครอง: ${answers.parent_name || '-'}`,
    `เบอร์: ${answers.phone || '-'}`,
    `นักเรียน: ${answers.student_name || '-'}`,
    `ระดับชั้น: ${answers.student_grade || '-'}`,
    `ปัญหา: ${answers.pain_point || '-'}`,
    `เวลาติดต่อ: ${answers.preferred_contact_time || '-'}`
  ].join('\n');
}

function MarkInvalid(conversation, state, reply_text, reason) {
  conversation.invalidCountByState = conversation.invalidCountByState || {};
  conversation.invalidCountByState[state] = Number(conversation.invalidCountByState[state] || 0) + 1;
  conversation.totalInvalidCount = Number(conversation.totalInvalidCount || 0) + 1;

  if (conversation.invalidCountByState[state] >= 3) {
    conversation.state = 'handover_to_staff';
    conversation.handoverReason = reason || 'invalid_answer_limit_reached';
    return {
      replyText: 'ขออภัยค่ะ ดูเหมือนบอทยังเก็บข้อมูลส่วนนี้ไม่สำเร็จ\nเดี๋ยวส่งเรื่องให้เจ้าหน้าที่เข้ามาช่วยดูแลต่อนะคะ 😊',
      handover: true
    };
  }

  return {
    replyText: reply_text || 'รบกวนตอบข้อมูลส่วนนี้อีกครั้งนะคะ 😊',
    handover: false
  };
}

let conversation = store.conversations[line_user_id] || CreateDefaultConversation();
conversation.currentStudentIndex = Number(conversation.currentStudentIndex || 0);
conversation.answers = conversation.answers || {};
conversation.invalidCountByState = conversation.invalidCountByState || {};
conversation.lastMessageAt = now_iso;
conversation.displayName = item.displayName || conversation.displayName || null;
conversation.pictureUrl = item.pictureUrl || conversation.pictureUrl || null;

let reply_text = '';
let should_reply = true;
let completed = false;
let crm_payload = null;
let should_notify_handover = false;
let notification_text = '';

const direct_decision = item.directDecision;
const consent_decision = item.consentDecision;
const rule_validation = item.ruleValidation;
const ai_validation = item.aiValidation;

if (direct_decision) {
  if (direct_decision.action === 'restart_registration') {
    conversation = CreateDefaultConversation();
    conversation.isRestartFlow = true;
    conversation.registrationBatchId = BuildRegistrationBatchId();
    conversation.state = 'waiting_consent';
    conversation.consentStatus = 'pending';
    conversation.answers = {};
    conversation.handoverReason = null;
    conversation.completedAt = null;
    conversation.handoverNotifiedAt = null;
    conversation.handoverReplyCount = 0;
    conversation.postCompletionReplyCount = 0;
    reply_text = BuildConsentIntroText();
  } else if (direct_decision.action === 'handover_to_staff') {
    conversation.state = 'handover_to_staff';
    conversation.handoverReason = direct_decision.reason;
    conversation.handoverReplyCount = Number(conversation.handoverReplyCount || 0) + 1;
    reply_text = conversation.handoverReplyCount <= 1 ? direct_decision.replyText : 'ได้แจ้งเรื่องให้เจ้าหน้าที่แล้วนะคะ 😊 ระหว่างนี้สามารถพิมพ์รายละเอียดเพิ่มเติมไว้ได้เลยค่ะ';
    should_reply = Boolean(reply_text);
  } else if (direct_decision.action === 'cancel_registration') {
    conversation.state = 'consent_declined';
    conversation.consentStatus = conversation.consentStatus === 'accepted' ? 'cancelled' : 'declined';
    conversation.handoverReason = direct_decision.reason;
    reply_text = direct_decision.replyText;
  }
} else if (consent_decision && !item.needsFieldValidation) {
  if (consent_decision.action === 'silent_handover') {
    conversation.state = 'handover_to_staff';
    conversation.handoverReplyCount = Number(conversation.handoverReplyCount || 0) + 1;
    reply_text = '';
    should_reply = false;
  } else if (consent_decision.action === 'post_completion_options') {
    conversation.state = 'handover_to_staff';
    conversation.postCompletionReplyCount = Number(conversation.postCompletionReplyCount || 0) + 1;
    reply_text = consent_decision.replyText;
    should_reply = true;
  } else {
    conversation.state = consent_decision.nextState || conversation.state;
    conversation.consentStatus = consent_decision.consentStatus || conversation.consentStatus;
    if (consent_decision.action === 'accept_consent') {
      conversation.consentAcceptedAt = conversation.consentAcceptedAt || now_iso;
      conversation.invalidCountByState.waiting_consent = 0;
    }
    reply_text = consent_decision.replyText;
  }
} else if (rule_validation && rule_validation.status === 'fail') {
  if (rule_validation.countInvalid === false) {
    reply_text = rule_validation.replyText || 'รบกวนแจ้งข้อมูลส่วนนี้เพิ่มเติมอีกนิดนะคะ 😊';
  } else {
    const invalid_result = MarkInvalid(conversation, conversation.state, rule_validation.replyText, rule_validation.reason);
    reply_text = invalid_result.replyText;
  }
} else if (ai_validation) {
  conversation.aiValidationSummary = conversation.aiValidationSummary || [];
  conversation.aiValidationSummary.push({
    state: conversation.state,
    is_valid: Boolean(ai_validation.is_valid),
    confidence: Number(ai_validation.confidence || 0),
    detected_intent: ai_validation.detected_intent || 'unknown',
    reason: ai_validation.reason || '',
    checked_at: now_iso
  });
  conversation.aiValidationSummary = conversation.aiValidationSummary.slice(-20);

  if (ai_validation.detected_intent === 'request_staff') {
    conversation.state = 'handover_to_staff';
    conversation.handoverReason = 'ai_detected_request_staff';
    reply_text = ai_validation.reply_text || 'ได้เลยค่ะ 😊 เดี๋ยวบอทส่งเรื่องให้เจ้าหน้าที่เข้ามาดูแลต่อนะคะ';
  } else if (ai_validation.detected_intent === 'restart') {
    conversation = CreateDefaultConversation();
    conversation.isRestartFlow = true;
    conversation.registrationBatchId = BuildRegistrationBatchId();
    reply_text = BuildConsentIntroText();
  } else if (ai_validation.detected_intent === 'cancel') {
    conversation.state = 'consent_declined';
    conversation.consentStatus = conversation.consentStatus === 'accepted' ? 'cancelled' : 'declined';
    conversation.handoverReason = 'ai_detected_cancel';
    reply_text = ai_validation.reply_text || 'เข้าใจค่ะ ตอนนี้บอทจะหยุดขั้นตอนลงทะเบียนไว้ก่อนนะคะ 😊';
  } else if (ai_validation.is_valid && Number(ai_validation.confidence || 0) >= 0.75) {
    const normalized_value = ai_validation.normalized_value || (rule_validation && rule_validation.normalizedValue) || item.normalizedText || '';
    const current_state = conversation.state;
    StoreAnswerForState(conversation, current_state, normalized_value);
    conversation.invalidCountByState[current_state] = 0;
    const next_state = MoveToNextState(current_state, conversation);
    conversation.state = next_state;
    if (next_state === 'ready_to_submit_crm') {
      conversation.completedAt = now_iso;
      completed = true;
      crm_payload = BuildCrmPayload(conversation);
      conversation.state = 'handover_to_staff';
      conversation.handoverReason = 'registration_completed';
      reply_text = [
        'ขอบคุณมากค่ะ 😊',
        'แอดมินได้รับข้อมูลเรียบร้อยแล้วนะคะ',
        '',
        'เดี๋ยวทีมงาน eiMaths จะติดต่อกลับตามช่วงเวลาที่แจ้งไว้',
        'เพื่อแนะนำการทดลองเรียนฟรี 2 คลาสให้น้องค่ะ',
        '',
        'หากต้องการกรอกข้อมูลใหม่ สามารถพิมพ์ “เริ่มใหม่” ได้เลยค่ะ'
      ].join('\n');
    } else {
      reply_text = QuestionForState(next_state, conversation);
    }
  } else {
    const should_count_invalid = !['ask_question', 'ask_clarification'].includes(ai_validation.detected_intent);
    if (should_count_invalid) {
      const invalid_result = MarkInvalid(conversation, conversation.state, ai_validation.reply_text, ai_validation.reason);
      reply_text = invalid_result.replyText;
    } else {
      reply_text = ai_validation.reply_text || `${questions[conversation.state] || 'รบกวนตอบข้อมูลส่วนนี้อีกครั้งนะคะ'}`;
    }
  }
} else if (rule_validation && rule_validation.status === 'pass') {
  const current_state = conversation.state;
  StoreAnswerForState(conversation, current_state, rule_validation.normalizedValue);
  conversation.invalidCountByState[current_state] = 0;
  const next_state = MoveToNextState(current_state, conversation);
  conversation.state = next_state;
  if (next_state === 'ready_to_submit_crm') {
    conversation.completedAt = now_iso;
    completed = true;
    crm_payload = BuildCrmPayload(conversation);
    conversation.state = 'handover_to_staff';
    conversation.handoverReason = 'registration_completed';
    reply_text = [
      'ขอบคุณมากค่ะ 😊',
      'แอดมินได้รับข้อมูลเรียบร้อยแล้วนะคะ',
      '',
      'เดี๋ยวทีมงาน eiMaths จะติดต่อกลับตามช่วงเวลาที่แจ้งไว้',
      'เพื่อแนะนำการทดลองเรียนฟรี 2 คลาสให้น้องค่ะ',
      '',
      'หากต้องการกรอกข้อมูลใหม่ สามารถพิมพ์ “เริ่มใหม่” ได้เลยค่ะ'
    ].join('\n');
  } else {
    reply_text = QuestionForState(next_state, conversation);
  }
} else {
  conversation.state = 'handover_to_staff';
  conversation.handoverReason = 'unhandled_decision_path';
  reply_text = 'ขออภัยค่ะ บอทยังดำเนินการต่อไม่สำเร็จ\nเดี๋ยวส่งเรื่องให้เจ้าหน้าที่ช่วยดูแลต่อนะคะ 😊';
}

if (conversation.state === 'handover_to_staff' && conversation.handoverReason !== 'registration_completed' && !conversation.handoverNotifiedAt) {
  should_notify_handover = true;
  conversation.handoverNotifiedAt = now_iso;
  notification_text = BuildHandoverNotificationText(conversation, conversation.handoverReason);
}

store.conversations[line_user_id] = conversation;

return {
  json: {
    ...item,
    completed,
    crmPayload: crm_payload,
    replyText: reply_text,
    shouldReply: should_reply && Boolean(reply_text),
    shouldNotifyHandover: should_notify_handover,
    notificationText: notification_text,
    lineUserId: line_user_id,
    conversationState: conversation.state,
    consentStatus: conversation.consentStatus,
    answers: conversation.answers,
    handoverReason: conversation.handoverReason || null
  }
};

const config = $('Normalize LINE Event').item.json.config || {};
const lead = $('Apply Conversation Decision').item.json.crmPayload || {};
const crm = $json || {};
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};
const crm_leads = Array.isArray(crm.leads) ? crm.leads : [];
const lead_ids = Array.isArray(crm.lead_ids) ? crm.lead_ids : (crm.lead_id ? [crm.lead_id] : []);
const lead_id = crm.id || crm.lead_id || crm.data?.id || crm.data?.lead_id || crm.data?.lead?.id || '';
const base_url = (config.crmBaseUrl || 'https://test-web.eimaths-th.com').replace(/\/$/, '');
const detail_url = crm.lead_list_url || crm.lead_detail_url || (lead_id ? base_url + '/admin/crm/leads/' + lead_id : base_url + '/admin/crm/leads');
const primary_crm_lead = crm_leads[0] || crm.data?.lead || crm.lead || {};
const source = primary_crm_lead.utm_source || lead.utm_source || lead.line_source || 'line';
const campaign = primary_crm_lead.utm_campaign || lead.utm_campaign || 'unknown';
const content = primary_crm_lead.utm_content || lead.utm_content || '-';
const line_name = lead.line_display_name || '-';
if (lead.line_user_id) {
  const conversation = store.conversations[lead.line_user_id] || {};
  const saved_lead_ids = Array.isArray(crm.lead_ids) ? crm.lead_ids : (crm.lead_id ? [crm.lead_id] : []);
  if (saved_lead_ids.length) {
    conversation.lastLeadIds = saved_lead_ids;
    conversation.lastLeadId = saved_lead_ids[0];
    conversation.lastLeadSavedAt = new Date().toISOString();
    store.conversations[lead.line_user_id] = conversation;
  }
}
